import{_ as l,c as i,o as e,ah as t}from"./chunks/framework.BkHe6ehV.js";const g=JSON.parse('{"title":"OpenAI 系列","description":"","frontmatter":{"title":"OpenAI 系列","date":"2025-12-06 11:52:04","create":"2025-12-06 11:52:04","categories":["openai"],"tags":["gpt5","gpt5-codex","gpt-oss","o1","o1mini","o3","o3-mini","GPT4","ChatGPT","InstructGPT","CodeX"],"readingStats":{"words":1986,"minutes":6,"images":0}},"headers":[],"relativePath":"posts/llm/industry/mainllm/07-openai-series.md","filePath":"posts/llm/industry/mainllm/07-openai-series.md","lastUpdated":1785944275000}'),a={name:"posts/llm/industry/mainllm/07-openai-series.md"};function s(c,o,r,d,n,u){return e(),i("div",null,o[0]||(o[0]=[t('<h2 id="变化点" tabindex="-1">变化点 <a class="header-anchor" href="#变化点" aria-label="Permalink to &quot;变化点&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">2026</div><p><strong>2026.09 · <a href="#_2609-gpt-6-astra-推理-rl、长任务、研发评测">GPT-6 Astra</a></strong></p><ul><li>扩大推理 RL 与长任务训练，强化多步工具执行和主动检查。</li><li>将模型研发任务纳入评测，关注端到端研发能力。</li></ul><p><strong>2026.02 · <a href="#_2602-gpt-5-3-codex-终端执行、长程-coding-agent">GPT-5.3-Codex</a></strong></p><ul><li>进一步结合代码推理、终端执行与计算机操作。</li><li>强化长程 Coding Agent，从局部修改扩展到连续工程任务。</li></ul></div><div class="custom-block info"><div class="custom-block-title">2025</div><p><strong>2025.09 · <a href="#_2509-gpt5-codex">GPT-5-Codex</a></strong></p><ul><li>围绕真实软件任务进行专项训练，强化代码修改与工具执行。</li><li>面向 Coding Agent 优化，支持持续完成多步开发任务。</li></ul><p><strong>2025.08 · <a href="#_2508-gpt5">GPT-5</a></strong></p><ul><li>强化复杂代码任务、推理与指令遵循，扩展通用模型的开发能力。</li></ul><p><strong>2025.08 · <a href="#_2508-gpt-oss">gpt-oss</a></strong></p><ul><li>开放 <code>120B / 20B</code> 两档 MoE 权重，支持本地部署。</li></ul></div><div class="custom-block info"><div class="custom-block-title">2025（续）</div><p><strong>2025.05 · <a href="#_2505-codex-1-o3、真实编码任务-rl">Codex-1</a></strong></p><ul><li>在 o3 基础上，用真实编码任务 RL 强化补丁生成、指令遵循与反复测试修正。</li><li>在仓库沙箱内读取文件、执行命令并验证结果，形成可交付的任务执行流程。</li></ul><p><strong>2025.04 · <a href="#_2409-o系列">o3 / o4-mini</a></strong></p><ul><li>继续强化复杂推理、代码与工具使用，扩展 o 系列的任务能力。</li></ul><p><strong>2025.04 · <a href="#_2309-gpt4">GPT-4.1</a></strong></p><ul><li>扩展至 <code>1M</code> 上下文，强化代码编辑与复杂指令遵循。(<a href="https://openai.com/index/gpt-4-1/" target="_blank" rel="noreferrer">blog</a>)</li></ul></div><div class="custom-block note"><div class="custom-block-title">2024 及以前</div><p><strong>2024.09 · <a href="#_2409-o系列">o1 / o1-mini</a></strong></p><ul><li>引入长思考的推理模型路线，先进行内部推理再回答。</li><li>面向数学、代码等复杂问题增加推理时计算。</li></ul><p><strong>2024.05–07 · <a href="#_2309-gpt4">GPT-4o / GPT-4o mini</a></strong></p><ul><li>GPT-4o 统一文本、图像与音频交互。</li><li>GPT-4o mini 进一步面向低成本、高吞吐场景。</li></ul><p><strong>2023.09 · <a href="#_2309-gpt4">GPT-4V</a></strong></p><ul><li>在 GPT-4 能力基础上接入视觉输入，扩展图像理解任务。</li></ul><p><strong>2022.11 · <a href="#_2211-chatgpt-gpt3-5">ChatGPT / GPT-3.5</a></strong></p><ul><li>通过对话式指令训练与 RLHF，将模型组织为多轮交互助手。</li></ul></div><div class="custom-block note"><div class="custom-block-title">2024 及以前（续）</div><p><strong>2022.03 报告 · <a href="#_2203-instructgpt">InstructGPT</a></strong></p><ul><li>建立 <code>SFT → Reward Model → PPO</code> 流程，以人类偏好对齐指令输出。</li></ul><p><strong>2021 · <a href="#code-x">Codex</a></strong></p><ul><li>基于 GPT-3 强化 GitHub 代码训练，将自然语言需求映射为代码。</li></ul><p><strong>2020 · <a href="#gpt-3">GPT-3</a></strong></p><ul><li>扩大语言模型预训练，突出无需梯度更新的 zero-shot / few-shot 学习。</li></ul><p><strong>2018–2019 · <a href="#gpt-1-2">GPT-1 / GPT-2</a></strong></p><ul><li>建立生成式预训练路线，通过扩大数据与模型提升通用语言能力。</li></ul></div><h2 id="_2609-gpt-6-astra-推理-rl、长任务、研发评测" tabindex="-1">(2609) GPT-6 Astra (推理 RL、长任务、研发评测) <a class="header-anchor" href="#_2609-gpt-6-astra-推理-rl、长任务、研发评测" aria-label="Permalink to &quot;(2609) GPT-6 Astra (推理 RL、长任务、研发评测)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">GPT-6 Astra：推理 RL 与研发任务</div><p><strong>来源与技术定位</strong></p><ul><li><a href="https://deploymentsafety.openai.com/gpt-6-astra" target="_blank" rel="noreferrer">GPT-6 Astra System Card</a>、<a href="https://openai.com/index/gpt-6-astra/" target="_blank" rel="noreferrer">官方发布</a>。</li><li>通过推理 RL 结合思考与工具执行，依据运行反馈调整后续步骤。</li><li>研发任务包括读取日志、修改代码、运行实验与提交产物，超出单轮答题。</li><li>系统卡介绍推理 RL 和数据过滤，未提供完整预训练、SFT、RL 配方。</li></ul></div><div class="custom-block note"><div class="custom-block-title">PostTrainBench Lite：评估模型后训练能力</div><p><strong>任务与资源</strong></p><ul><li>Agent 获得已有 Base 模型，自行准备数据、运行训练并提交 checkpoint。</li><li>覆盖 <code>3 个 Base 模型 × 4 个任务</code>；每次提供 <code>1 张 H100, 5 小时</code>。</li></ul><p><strong>评分方法</strong></p><ul><li>提交模型相对 Base 的增益，除以参考 Instruct 相对 Base 的增益，截到 <code>[0,1]</code>。</li><li>例：Base <code>40</code>、Instruct <code>60</code>、提交模型 <code>50</code>，得分 <code>0.5</code>；使用评测数据训练的提交计零分。</li><li>固定资源约束让评测同时覆盖实验选择、反馈利用与实际产物质量。</li></ul></div><div class="custom-block important"><div class="custom-block-title">公开表现</div><p><strong>研发与电脑操作</strong></p><ul><li>内部研究调试任务 <code>78.05%</code>，任务要求处理研究代码与实验问题。</li><li>OSWorld 2.0 官方延迟模拟：Astra <code>72.6</code>、约 <code>40 分钟/任务</code>。</li><li>对照 GPT-5.6 Sol 为 <code>65.7</code>、约 <code>75 分钟/任务</code>，得分与执行效率同时改善。</li></ul></div><h2 id="_2602-gpt-5-3-codex-终端执行、长程-coding-agent" tabindex="-1">(2602) GPT-5.3-Codex (终端执行、长程 Coding Agent) <a class="header-anchor" href="#_2602-gpt-5-3-codex-终端执行、长程-coding-agent" aria-label="Permalink to &quot;(2602) GPT-5.3-Codex (终端执行、长程 Coding Agent)&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">GPT-5.3-Codex：完整开发工作流</div><p><strong>来源与能力</strong></p><ul><li><a href="https://openai.com/index/introducing-gpt-5-3-codex/" target="_blank" rel="noreferrer">Introducing GPT-5.3-Codex</a>。</li><li>整合 Coding 与通用推理，从代码修改扩展到终端执行、环境处理和测试验证。</li><li>工具反馈进入后续决策，执行过程中可接收新要求，调整已有计划与操作。</li></ul><p><strong>模型辅助研发</strong></p><ul><li>早期版本用于定位训练问题、诊断评测失败与辅助部署，研发团队结合实验反馈决策。</li><li>发布材料未给出完整训练数据量和 SFT/RL 超参。</li></ul></div><div class="custom-block important"><div class="custom-block-title">公开表现(GPT-5.2-Codex → 5.3-Codex)</div><p><strong>Xhigh 评测</strong></p><ul><li>SWE-bench Pro Public <code>56.4 → 56.8</code>，仓库修复增益较小。</li><li>Terminal-Bench 2.0 <code>64.0 → 77.3</code>，OSWorld-Verified <code>38.2 → 64.7</code>。</li><li>主要收益在终端和电脑操作，体现连续执行能力向代码补丁之外扩展。</li></ul></div><h2 id="数据集" tabindex="-1">数据集 <a class="header-anchor" href="#数据集" aria-label="Permalink to &quot;数据集&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">数据集</div><ul><li><a href="https://huggingface.co/datasets/openai/gdpval" target="_blank" rel="noreferrer">GDPVal</a></li></ul></div><h2 id="_2509-gpt5-codex" tabindex="-1">(2509 )GPT5-Codex <a class="header-anchor" href="#_2509-gpt5-codex" aria-label="Permalink to &quot;(2509 )GPT5-Codex&quot;">​</a></h2><div class="custom-block caution"><div class="custom-block-title">参考文章</div><ul><li><a href="https://openai.com/zh-Hans-CN/index/introducing-upgrades-to-codex/" target="_blank" rel="noreferrer">Codex 全面升级</a></li></ul></div><div class="custom-block tip"><div class="custom-block-title">GPT5-Codex 概览</div><p><strong>核心技术</strong></p><ul><li>Agentic Coding，关键技术： <ul><li><code>真实软件工程</code> <code>RL学习</code>，</li><li><code>沙盒执行</code>，</li><li>可控工具使用等。</li></ul></li></ul><p><strong>关键结果</strong></p><ul><li>外部评论：效果比GPT5好</li></ul></div><h2 id="_2508-gpt5" tabindex="-1">(2508) GPT5 <a class="header-anchor" href="#_2508-gpt5" aria-label="Permalink to &quot;(2508) GPT5&quot;">​</a></h2><div class="custom-block caution"><div class="custom-block-title">参考文章</div><ul><li>(2508) <a href="https://openai.com/zh-Hans-CN/index/gpt-5-system-card/" target="_blank" rel="noreferrer">GPT-5 系统卡</a></li><li>(2508) <a href="https://openai.com/zh-Hans-CN/index/introducing-gpt-5-for-developers/" target="_blank" rel="noreferrer">隆重推出面向开发人员的 GPT-5</a></li><li>(2508) <a href="https://openai.com/zh-Hans-CN/index/introducing-gpt-5/" target="_blank" rel="noreferrer">隆重推出 GPT-5</a></li></ul></div><div class="custom-block tip"><div class="custom-block-title">GPT5 概览</div><p><strong>GPT5</strong></p><ul><li>最强大的代码模型。</li></ul></div><h2 id="_2508-gpt-oss" tabindex="-1">(2508) GPT-OSS <a class="header-anchor" href="#_2508-gpt-oss" aria-label="Permalink to &quot;(2508) GPT-OSS&quot;">​</a></h2><div class="custom-block caution"><div class="custom-block-title">参考文章</div><ul><li><a href="https://openai.com/zh-Hans-CN/index/introducing-gpt-oss/" target="_blank" rel="noreferrer">隆重推出 gpt-oss</a></li></ul></div><div class="custom-block tip"><div class="custom-block-title">GPT-OSS 概览</div><p><strong>核心</strong></p><ul><li>MoE，OpenAI 开源。</li><li>gpt-oss-120b, gpt-oss-20b</li></ul></div><h2 id="_2505-codex-1-o3、真实编码任务-rl" tabindex="-1">(2505) Codex-1 (o3、真实编码任务 RL) <a class="header-anchor" href="#_2505-codex-1-o3、真实编码任务-rl" aria-label="Permalink to &quot;(2505) Codex-1 (o3、真实编码任务 RL)&quot;">​</a></h2><div class="custom-block danger"><div class="custom-block-title">Codex-1</div><p><strong>参考链接</strong></p><ul><li><a href="https://openai.com/index/introducing-codex/" target="_blank" rel="noreferrer">blog</a></li></ul><p><strong>核心变化</strong></p><ul><li>基于 <strong>o3</strong>，在多种真实编码环境中进行 RL，面向仓库级软件任务。</li><li>训练目标包括遵循指令、生成符合偏好的补丁，以及反复测试和修正。</li><li>任务从单段代码生成，扩展到读取仓库、修改文件和验证结果。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">仓库沙箱与验证</div><p><strong>执行过程</strong></p><ul><li>每个任务使用独立环境，模型可读取和编辑文件、执行终端命令。</li><li>通过测试、linter 和类型检查获得反馈，继续修正代码。</li><li>交付补丁与终端日志，提供可检查的执行证据。</li></ul><p><strong>首发评测设置</strong></p><ul><li>SWE-bench Verified 使用 <code>192K</code> 上下文、<code>medium</code> reasoning effort。</li><li>排除内部环境无法运行的 <code>23</code> 个任务，评测子集为 <code>477</code> 题。</li></ul></div><h2 id="_2409-o系列" tabindex="-1">(2409) O系列 <a class="header-anchor" href="#_2409-o系列" aria-label="Permalink to &quot;(2409) O系列&quot;">​</a></h2><div class="custom-block caution"><div class="custom-block-title">参考文章</div><ul><li>(2409) <a href="https://openai.com/zh-Hans-CN/index/introducing-openai-o1-preview/" target="_blank" rel="noreferrer">隆重推出 OpenAI o1-preview</a></li><li>(2504) <a href="https://openai.com/zh-Hans-CN/index/introducing-o3-and-o4-mini/" target="_blank" rel="noreferrer">隆重推出 OpenAI o3 和 o4-mini</a></li></ul></div><div class="custom-block tip"><div class="custom-block-title">O系列概览</div><p><strong>核心思想</strong></p><ul><li>以<code>推理思维链</code>、<code>内部深思</code>为核心。旨在解决复杂问题，比如编程等。</li></ul><p><strong>o1, o1-mini</strong></p><ul><li>首次引入 Step-by-step 内部推理，思考后再做回答。</li><li>o1-mini在软件任务上效果好。</li></ul><p><strong>o3, o3-mini</strong></p><ul><li><code>扩展上下文长度</code>、<code>优化了repo-level</code>的代码编辑能力等。</li><li>SWE-Bench超越GPT4。</li></ul></div><h2 id="_2309-gpt4" tabindex="-1">(2309) GPT4 <a class="header-anchor" href="#_2309-gpt4" aria-label="Permalink to &quot;(2309) GPT4&quot;">​</a></h2><div class="custom-block caution"><div class="custom-block-title">参考文章</div><ul><li>(2309)<a href="https://openai.com/index/gpt-4v-system-card/" target="_blank" rel="noreferrer">GPT-4V(ision) system card</a></li><li>(2405) <a href="https://openai.com/zh-Hans-CN/index/hello-gpt-4o/" target="_blank" rel="noreferrer">你好 GPT-4o</a></li><li>(2407) <a href="https://openai.com/zh-Hans-CN/index/gpt-4o-mini-advancing-cost-efficient-intelligence/" target="_blank" rel="noreferrer">GPT-4o mini：推动高性价比智能的发展</a></li></ul></div><div class="custom-block tip"><div class="custom-block-title">GPT4 概览</div><p><strong>关键结果</strong></p><ul><li>相比GPT3，具有更强推理和代码能力。</li><li>GPT4-Turbo：提高生产环境效率。</li><li>GPT-4o：多模态，集成文本、<code>图像</code>和音频， 保留强大代码能力。</li><li>GPT-4o-mini：强调成本效率。</li><li>GPT-4.1：<code>扩展长上下文</code>和代码编辑能力，可在Repo-Level做编辑。</li></ul></div><h2 id="_2211-chatgpt-gpt3-5" tabindex="-1">(2211) ChatGPT/GPT3.5 <a class="header-anchor" href="#_2211-chatgpt-gpt3-5" aria-label="Permalink to &quot;(2211) ChatGPT/GPT3.5&quot;">​</a></h2><div class="custom-block caution"><div class="custom-block-title">参考文章</div><ul><li>(2211) <a href="https://openai.com/zh-Hans-CN/index/chatgpt/" target="_blank" rel="noreferrer">隆重推出 ChatGPT</a></li><li>(2303) <a href="https://openai.com/index/chatgpt-plugins/##code-interpreter" target="_blank" rel="noreferrer">ChatGPT plugins</a></li></ul></div><div class="custom-block tip"><div class="custom-block-title">ChatGPT 概览</div><p><strong>核心技术</strong></p><ul><li>基于InstructGPT开发，GPT3拓展版本，增加以下能力 <ul><li>额外的<code>指令微调</code>和<code>RLHF</code></li><li><code>稳定的多轮对话能力</code>，最核心。</li><li>增加<code>安全拒识行为</code>等内容。</li></ul></li></ul><p><strong>关键结果</strong></p><ul><li>大火。</li><li>第一个被广泛应用的对话式LLM。</li><li>具有较好编程能力，在各IDE工作流中使用。</li></ul></div><h2 id="_2203-instructgpt" tabindex="-1">(2203) InstructGPT <a class="header-anchor" href="#_2203-instructgpt" aria-label="Permalink to &quot;(2203) InstructGPT&quot;">​</a></h2><div class="custom-block caution"><div class="custom-block-title">参考文章</div><ul><li><a href="https://arxiv.org/abs/2203.02155" target="_blank" rel="noreferrer">paper</a></li></ul></div><div class="custom-block tip"><div class="custom-block-title">Instruct GPT 概览</div><p><strong>问题背景</strong></p><ul><li>GPT3虽然懂得多，但<code>经常答非所问</code>、<code>不安全</code>、和人类需求不对齐。</li></ul><p><strong>核心技术</strong></p><ul><li>通过<code>人类反馈RLHF</code>，和<code>人类偏好进行对齐</code>。OpenAI 护城河。</li><li>人类偏好 <code>Reward Mode</code>l (偏好打分)、<code>PPO</code>训练等。</li></ul><p><strong>关键结果</strong></p><ul><li>模型更受人类青睐：<code>幻觉更少</code>、<code>行为更安全</code>。</li><li><code>小参数对齐模型</code> <code>超越</code> <code>大参数GPT3</code>模型</li></ul></div><h2 id="code-x" tabindex="-1">Code X <a class="header-anchor" href="#code-x" aria-label="Permalink to &quot;Code X&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">Code X 概览</div><p><strong>核心技术</strong></p><ul><li>GPT3编程特别版，<code>GPT3</code>+<code>GitHub代码预训练</code>。</li></ul><p><strong>关键结果</strong></p><ul><li>在<code>HumanEval代码生成</code>和补全Benchmark上表现不错，<code>早期的代码对齐LLM</code>。</li><li>催生了Github Copilot这种商业产品，解决了<code>自然语言</code> -&gt; <code>可执行代码</code>的翻译问题。</li></ul></div><h2 id="gpt-3" tabindex="-1">GPT 3 <a class="header-anchor" href="#gpt-3" aria-label="Permalink to &quot;GPT 3&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">GPT3 概览</div><p><strong>核心技术</strong></p><ul><li>在<code>大规模web</code>和<code>文本</code>数据上做<code>ScaleUp</code>。</li></ul><p><strong>关键结果</strong></p><ul><li>强大的<code>上下文学习能力</code>(zero-shot/few-shot)，<code>无需梯度更新</code>也能适应理解、代码、推理等任务。</li></ul></div><h2 id="gpt-1-2" tabindex="-1">GPT 1-2 <a class="header-anchor" href="#gpt-1-2" aria-label="Permalink to &quot;GPT 1-2&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">GPT1-2 系列概览</div><p><strong>核心</strong></p><ul><li>验证了<code>生成式预训练</code>可行，开源了权重。</li></ul></div>',45)]))}const h=l(a,[["render",s]]);export{g as __pageData,h as default};
